/* @author MILO-GAO(高振銘)@2020 */ package page2020.view.bs4;import java.util.Arrays;import java.util.List;import page2020.unit.Urule;import page2020.util.EmptyUtil;import page2020.view.Content;import page2020.view.Value;import page2020.view.bs4.B4show.D;import page2020.view.html5.H5br;import page2020.view.html5.H5div;import page2020.view.html5.H5form;import page2020.view.html5.H5hr;import page2020.view.html5.H5input;public class B4form extends H5form {	public static final String formInline = "form-inline";	public static final String formGroup = "form-group";	private boolean inline = false;	private int[] numbers = new int[] { 12, 6, 4, 3 };	private B4row row;	private B4col col;	private int index = -1;	public B4form() {		super();	}	public B4form construct(boolean inline) {		this.inline = inline;		super.append(new H5div().cssClass(D.none));		if (! inline) {			this.initialStack();		}		return this;	}	public B4form destruct() {		H5div template = (H5div) super.get(0);		if (template.count() == 0) {			super.remove(0);		}		if (! inline) {			this.finalStack();		}		return this;	}	public B4form device(int... numbers) {		if (! this.inline) {			this.numbers = B4col.numbers(numbers);		}		return this;	}	public B4form device(String device) {		if (! this.inline) { 			this.numbers = B4col.numbers(device);		}		return this;	}	public B4form row(int... numbers) {		if (! this.inline) {			if (this.row.count() > 1) {				this.finalStack();				this.initialStack();							}			this.row.device(numbers);		}		return this;	}	public B4form row(String device) {		return this.row(B4col.numbers(device));	}	public B4form row() {		return this.row(new int[] {});	}	public B4form col(int... numbers) {		if (! this.inline) {			this.col.device(numbers);		}		return this;	}	public B4form col(String device) {		return this.col(B4col.numbers(device));	}	public B4form col() {		return this.col(new int[] {});	}	public B4form hr() {		if (! this.inline) {			this.finalStack();			super.append(new H5hr());			this.initialStack();		} else {			super.append(new H5hr());		}		return this;	}	public B4form br() {		if (! this.inline) {			this.finalStack();			super.append(new H5br());			this.initialStack();		} else {			super.append(new H5br());		}		return this;	}	public B4form rule(String code) {		int pos = code.indexOf(";");		String icon = null;		if (pos >= 0) {			String[] tokens = code.split(";");			icon = tokens[0];			code = tokens[1];		}		B4element rule = new Urule(1, true).my(1);		if (icon != null) {			rule.icon(icon);		}		rule.code(code);		if (! this.inline) {			this.finalStack();			super.append(rule);			this.initialStack();		} else {			super.append(rule);		}		return this;			}	public B4form template(H5input input) {		H5div template = (H5div) super.get(0);		template.append(input);		return this;	}	@Override	public B4form append(Content<?> c) {		if (EmptyUtil.not(c)) {			if (this.inline) {				super.append(c);			} else {				this.col.append(c);				this.row.append(this.column());			}		}		return this;	}	@Override	public B4form append(Content<?>... c) {		if (EmptyUtil.not((Object[]) c)) {			if (this.inline) {				super.append(c);			} else {				if (c.length == 1) {					this.col.append(c);				} else {					this.col.append(new B4element().cssClass(formGroup).append(c));				}				this.row.append(this.column());							}		}		return this;	}	@Override	public B4form append(List<Content<?>> c) {		if (EmptyUtil.not(c)) {			if (this.inline) {				super.append(c);			} else {				if (c.size() == 1) {					this.col.append(c);				} else {					this.col.append(new B4element().cssClass(formGroup).append(c));				}				this.row.append(this.column());			}		}		return this;	}	@Override	public B4form text(String text) {		if (this.inline) {			super.append(new Value().text(text));		} else {			this.col.append(new Value().text(text));			this.row.append(this.column());					}		return this;	}	@Override	public B4form value(Object value) {		if (this.inline) {			super.append(new Value().value(value));		} else {			this.col.append(new Value().value(value));			this.row.append(this.column());					}		return this;	}	@Override	public void build() {		if ((! this.inline) && this.numbers != null && super.count() > 0) {			super.getContents().forEach(c -> {				if (c instanceof B4row) {					B4row row = (B4row) c;					if (row.getNumbers() == null) {						row.setNumbers(Arrays.copyOf(this.numbers, this.numbers.length));					}				}			});		}		this.index = -1;		super.build();	}	@Override	public B4form copy() {		B4form bean = (B4form) super.copy();		bean.setNumbers(Arrays.copyOf(this.numbers, this.numbers.length));		return bean;	}	private B4col column() {		B4col column = new B4col();		column.data(B4col.col, ++index);		this.col = column;		return column;	}	private void initialStack() {		this.row = new B4row(true);		this.column();		super.append(this.row.append(this.col));	}	private void finalStack() {		if (this.row != null && this.col != null) {			if (this.col.count() == 0) {				this.row.remove(this.row.count() - 1);			}			if (this.row.count() == 0) {				super.remove(super.count() - 1);			}		}		this.row = null;		this.col = null;	}	public boolean isInline() {		return inline;	}	public void setInline(boolean inline) {		this.inline = inline;	}	public int[] getNumbers() {		return numbers;	}	public void setNumbers(int[] numbers) {		this.numbers = numbers;	}	public B4row getRow() {		return row;	}	public void setRow(B4row row) {		this.row = row;	}	public B4col getCol() {		return col;	}	public void setCol(B4col col) {		this.col = col;	}}